# ================================================================ 2.1.1–2.1.2
L(
    id="az305-relational", title="Design relational data storage and service tiers", objectives=["AZ305-2.1.1", "AZ305-2.1.2"], minutes=45,
    objective="Recommend a relational data platform (SQL Database, SQL Managed Instance, SQL Server on VMs, open-source databases) and the right purchasing model, service tier and compute tier.",
    prereqs=["Basic SQL Server or relational database concepts"],
    foundation=[
        "Relational data (tables, rows, transactions) has three Azure SQL homes: SQL Database (most managed), SQL Managed Instance (most compatible PaaS) and SQL Server on a VM (most control).",
        "Pick the most managed option that still runs the app. Then pick a tier: how fast, how big, how highly available.",
        "PostgreSQL and MySQL apps use Azure Database for PostgreSQL or MySQL flexible server.",
    ],
    engineer=[
        "Platform choice: Azure SQL Database (single database or elastic pool; database-scoped features; ideal for new cloud apps); Azure SQL Managed Instance (instance-scoped features: SQL Agent, cross-database queries, Database Mail, CLR, Service Broker, linked servers; VNet-injected; best for lifting many SQL Server databases with few changes; the Managed Instance link supports hybrid DR with SQL Server 2016+); SQL Server on Azure VMs (OS access, SSRS/SSIS/SSAS on the same machine, unsupported versions or third-party agents).",
        "Purchasing models: DTU (bundled compute, storage and I/O in Basic, Standard, Premium; simple) or vCore (choose vCores, memory and storage separately; use Azure Hybrid Benefit and reserved capacity to cut cost; recommended for flexibility).",
        "vCore service tiers: General Purpose (balanced, remote premium storage, budget-friendly), Business Critical (local SSD, lowest latency, three secondary replicas with one readable, In-Memory OLTP), Hyperscale (up to 128 TB, near-instant backups, fast scale, up to 4 high-availability replicas and named replicas). Managed Instance offers General Purpose (including Next-gen) and Business Critical.",
        "Compute tiers: provisioned (fixed vCores, predictable workloads) or serverless (auto-scales between min and max vCores, billed per second; can auto-pause when idle in General Purpose; good for intermittent or unpredictable use). Elastic pools share eDTUs or vCores across many databases with different peak times (multi-tenant SaaS). New databases can use the Azure SQL Database free offer for experiments.",
    ],
    anim=("az305-sql-sim", "Pick the relational service, then the tier and compute model."),
    example=("Modernising a line-of-business estate", [
        "80 SQL Server databases with SQL Agent jobs and cross-database queries move to SQL Managed Instance (Business Critical for the order system, General Purpose for the rest) with Azure Hybrid Benefit.",
        "A new customer portal uses SQL Database serverless; 300 small tenant databases share an elastic pool; one 30 TB analytics-heavy database moves to Hyperscale.",
    ]),
    config=cfg(["Create Azure SQL > SQL databases (single or elastic pool) / SQL managed instances / SQL virtual machines.", "Compute + storage: service tier, compute tier (provisioned/serverless), vCores, max size, backup storage redundancy."],
               cli="az sql db create -g rg-data -s sql-contoso -n db-portal --edition GeneralPurpose --compute-model Serverless \\\n  --family Gen5 --capacity 2 --auto-pause-delay 60\naz sql elastic-pool create -g rg-data -s sql-contoso -n pool-tenants --edition GeneralPurpose --family Gen5 --capacity 8",
               ps="New-AzSqlDatabase -ResourceGroupName rg-data -ServerName sql-contoso -DatabaseName db-portal -Edition GeneralPurpose -ComputeModel Serverless -ComputeGeneration Gen5 -VCore 2 -AutoPauseDelayInMinutes 60"),
    lab=lab("Choose the relational service and tier for each workload.", [("sql-store", "relational service"), ("sql-tier", "tier or compute model")], ["Answer every case in both trainers."],
            ["Managed Instance for instance-level features", "Hyperscale for very large databases; serverless for intermittent use"], ["Choosing a VM when PaaS would run the app", "Business Critical for a dev database"]),
    troubleshooting=[("Migration to SQL Database fails because the app uses SQL Agent and cross-database queries.", "Instance-level features are not in SQL Database.", "Use SQL Managed Instance."),
                     ("A serverless database has a delay on the first query each morning.", "Auto-pause resumes on first connection.", "Increase the auto-pause delay, disable auto-pause, or use provisioned compute.")],
    comparisons=[("SQL Database vs Managed Instance", "Database-scoped PaaS vs instance-scoped PaaS with near-full SQL Server compatibility in your VNet."), ("DTU vs vCore", "Bundled simplicity vs independent choice of compute and storage with Hybrid Benefit.")],
    misconceptions=[("Business Critical is always the best choice.", "It costs much more; use it for latency-sensitive OLTP or when you need the readable replica."), ("Serverless means unlimited scale.", "It scales between the min and max vCores you set.")],
    decisions=["Most managed service that runs the app.", "vCore model for flexibility and Hybrid Benefit.", "Tier by latency, size and availability; serverless for intermittent use; elastic pools for many small databases."],
    docs=[("Azure SQL: IaaS vs PaaS", SQL + "azure-sql-iaas-vs-paas-what-is-overview"), ("vCore service tiers", SQL + "database/service-tiers-sql-database-vcore"), ("Serverless compute tier", SQL + "database/serverless-tier-overview"), ("Elastic pools", SQL + "database/elastic-pool-overview"), ("Hyperscale service tier", SQL + "database/service-tier-hyperscale")],
    walk_=("Put relational data on the most managed Azure SQL option that fits, at the right size and price.",
           ["SQL Database, Managed Instance or SQL on a VM", "DTU vs vCore", "General Purpose, Business Critical, Hyperscale", "Provisioned, serverless or elastic pool"],
           row(0, ("app", "Application", "compute"), ("sqldb", "SQL Database", "database", "most managed"), ("mi", "SQL Managed Instance", "database", "most compatible"))
           + row(1, ("vm", "SQL Server on a VM", "compute", "most control"), ("gp", "General Purpose", "service"), ("bc", "Business Critical", "service"), ("hs", "Hyperscale", "service"))
           + row(2, ("sl", "Serverless", "cost", "pay per second"), ("pool", "Elastic pool", "cost", "many databases")),
           [S("problem", "Problem", "Where should this database live?", "SQL Server databases are moving to Azure. Some use instance features, some are huge, some are idle most of the day.", add=["app"]),
            S("concept", "Platforms", "Three Azure SQL homes", "SQL Database: fully managed, per database. Managed Instance: almost everything SQL Server does (SQL Agent, cross-database queries) as PaaS in your VNet. SQL Server on a VM: full control when nothing else fits.", add=["sqldb", "mi", "vm"], edges=[("app", "sqldb"), ("app", "mi"), ("app", "vm")], learn=[0], tip="Start from the most managed option and move right only for a reason."),
            S("concept", "Buying", "DTU or vCore", "DTU bundles compute, storage and I/O into simple sizes. vCore lets you choose compute and storage separately and use Azure Hybrid Benefit and reservations — usually the better choice.", learn=[1]),
            S("technique", "Tiers", "Pick the tier by need", "General Purpose: balanced and cheaper. Business Critical: fastest storage, a free readable replica. Hyperscale: up to 128 TB with fast scaling.", add=["gp", "bc", "hs"], edges=[("sqldb", "gp"), ("sqldb", "bc"), ("sqldb", "hs")], learn=[2]),
            S("technique", "Compute", "Pay for what you use", "Serverless scales vCores automatically and can pause when idle. Elastic pools let hundreds of small databases share one set of resources.", add=["sl", "pool"], edges=[("gp", "sl"), ("sqldb", "pool")], learn=[3]),
            S("recap", "Recap", "Relational design", "Platform, model, tier, compute.", recap=["SQL DB → MI (instance features) → VM (OS control)", "vCore + Hybrid Benefit", "GP / BC (latency, readable replica) / Hyperscale (128 TB)", "Serverless for intermittent; elastic pool for many DBs"])]),
)
qa("AZ305-2.1.1", 2, "scenario", "You migrate 40 SQL Server databases that use SQL Agent jobs, cross-database queries and Database Mail. You want PaaS with minimal changes. What do you recommend?", [("Azure SQL Managed Instance", "Correct."), ("Azure SQL Database single databases", "No SQL Agent or cross-database queries."), ("SQL Server on Azure VMs", "Works but is IaaS, not PaaS."), ("Azure Cosmos DB", "Not relational SQL Server.")], "a", "Managed Instance supports instance-scoped SQL Server features as PaaS.", SQL + "managed-instance/sql-managed-instance-paas-overview")
qa("AZ305-2.1.1", 2, "scenario", "An application requires SQL Server Reporting Services on the same server and a third-party backup agent installed on the OS. What do you recommend?", [("SQL Server on Azure VMs", "Correct: OS access and full feature set."), ("SQL Managed Instance", "No OS access."), ("SQL Database", "No OS access."), ("Azure Database for MySQL", "Different engine.")], "a", "Only a VM gives OS-level control.", SQL + "virtual-machines/windows/sql-server-on-azure-vm-iaas-what-is-overview")
qa("AZ305-2.1.1", 2, "single", "A new cloud-native app needs one relational database with the least administration. What do you recommend?", [("Azure SQL Database", "Correct."), ("SQL Managed Instance", "More than needed."), ("SQL Server on a VM", "Most administration."), ("Azure Table Storage", "Not relational.")], "a", "SQL Database is the most managed relational option for new apps.", SQL + "azure-sql-iaas-vs-paas-what-is-overview")
qa("AZ305-2.1.2", 2, "scenario", "A database is 45 TB and growing, and must scale compute quickly. Which tier?", [("Hyperscale", "Correct: up to 128 TB and fast scaling."), ("General Purpose", "Limited to a few TB."), ("Business Critical", "Limited size."), ("Basic (DTU)", "Very small.")], "a", "Hyperscale separates compute and storage for very large databases.", SQL + "database/service-tier-hyperscale")
qa("AZ305-2.1.2", 2, "scenario", "A SaaS vendor has 250 small tenant databases. Each is busy at different times. Cost must be minimised. What do you recommend?", [("An elastic pool", "Correct: databases share pooled resources."), ("250 provisioned Business Critical databases", "Very expensive."), ("One Hyperscale database", "Breaks tenant isolation."), ("SQL Server on one VM", "More administration.")], "a", "Elastic pools suit many databases with varying, non-overlapping usage.", SQL + "database/elastic-pool-overview")
qa("AZ305-2.1.2", 3, "scenario", "A test database is used for about 2 hours a day at unpredictable times. You want to pay as little as possible. What do you recommend?", [("General Purpose serverless with auto-pause", "Correct."), ("Business Critical provisioned", "Expensive and always running."), ("Hyperscale provisioned with named replicas", "Overkill."), ("DTU Premium", "Always billed.")], "a", "Serverless bills per second of use and pauses when idle (General Purpose).", SQL + "database/serverless-tier-overview")

# ================================================================ 2.1.3–2.1.4
L(
    id="az305-relational-scale-protect", title="Design relational scalability and data protection", objectives=["AZ305-2.1.3", "AZ305-2.1.4"], minutes=40,
    objective="Recommend how a relational database scales (up, read scale-out, pools, sharding, Hyperscale) and how its data is protected (encryption, masking, row-level security, auditing, threat protection).",
    prereqs=[("Relational data storage and tiers", "AZ305-2.1.1", "az305-relational")],
    foundation=[
        "When a database gets busier you can give it more power (scale up), send reads to copies (scale out reads), share resources across databases (pools), or split the data across databases (sharding).",
        "Protecting data means encrypting it, hiding what people shouldn't see, limiting which rows they read, and recording who did what.",
    ],
    engineer=[
        "Scalability: vertical scaling changes vCores or service objective online (brief reconnect); read scale-out routes ApplicationIntent=ReadOnly connections to a readable replica (Business Critical, Premium, Hyperscale); Hyperscale adds high-availability replicas and up to 30 named replicas for read workloads; elastic pools for many databases; horizontal sharding with elastic database tools (shard map manager) for data beyond one database; geo-replicas can also serve reads in other regions.",
        "Encryption: TDE encrypts data at rest by default (service-managed or customer-managed key in Key Vault); TLS for data in transit; Always Encrypted encrypts sensitive columns in the client driver so the database engine and DBAs never see plaintext (secure enclaves allow richer queries).",
        "Access to data: Microsoft Entra authentication for users and managed identities; dynamic data masking hides values in results for non-privileged users (not encryption); row-level security filters rows with security predicates; ledger tables give tamper evidence.",
        "Monitoring and threat protection: auditing to storage, Log Analytics or Event Hubs; Microsoft Defender for SQL (vulnerability assessment, threat detection such as SQL injection alerts); data discovery and classification. Network protection: private endpoints and disabling public access.",
    ],
    anim=("az305-sql-scale-sim", "Pick a scaling technique and the right data protection feature."),
    example=("Scaling and securing a payments database", [
        "The Business Critical database routes reporting to its readable replica with ApplicationIntent=ReadOnly and scales up for month-end. Card numbers use Always Encrypted; support staff see masked phone numbers.",
        "Row-level security limits each merchant to its own rows. Auditing goes to Log Analytics, and Defender for SQL alerts on injection attempts.",
    ]),
    config=cfg(["SQL database > Compute + storage: scale vCores; Read scale-out setting.", "SQL database > Security: Auditing, Dynamic data masking, Microsoft Defender for Cloud, Transparent data encryption."],
               cli="az sql db update -g rg-data -s sql-contoso -n db-pay --capacity 16\naz sql db audit-policy update -g rg-data -s sql-contoso -n db-pay --state Enabled --lat-destination-type LogAnalytics --log-analytics-workspace-resource-id <law-id>",
               ps="Set-AzSqlDatabase -ResourceGroupName rg-data -ServerName sql-contoso -DatabaseName db-pay -VCore 16"),
    lab=lab("Choose how to scale and protect each database.", [("sql-scale", "scaling technique"), ("sql-protect", "protection feature")], ["Answer every case in both trainers."],
            ["Read scale-out for reports; sharding for data beyond one database", "Always Encrypted hides data from DBAs"], ["Using masking as if it were encryption", "Scaling up when reads could go to a replica"]),
    troubleshooting=[("Reports still hit the primary after enabling read scale-out.", "Connection string lacks ApplicationIntent=ReadOnly.", "Add ApplicationIntent=ReadOnly to the reporting connection string."),
                     ("A DBA can still see credit card numbers.", "Only TDE (at rest) is used.", "Use Always Encrypted for those columns.")],
    comparisons=[("TDE vs Always Encrypted", "TDE protects files at rest; Always Encrypted protects columns from anyone without the client key, including DBAs."), ("Dynamic data masking vs row-level security", "Masking hides parts of values; RLS hides whole rows.")],
    misconceptions=[("Dynamic data masking encrypts data.", "It only changes what non-privileged users see in results."), ("Scaling up is the only way to handle more load.", "Read scale-out, pools and sharding also help.")],
    decisions=["Route reads to replicas before scaling up.", "Always Encrypted for highly sensitive columns.", "Auditing + Defender for SQL on production."],
    docs=[("Read scale-out", SQL + "database/read-scale-out"), ("Scale out with elastic database tools", SQL + "database/elastic-scale-introduction"), ("Azure SQL security overview", SQL + "database/security-overview"), ("Always Encrypted", ML + "sql/relational-databases/security/encryption/always-encrypted-database-engine")],
    walk_=("Keep a database fast as it grows, and keep its data safe from the wrong eyes.",
           ["Scale up, read scale-out, pools, sharding", "Encryption at rest and in use", "Masking, row-level security, auditing"],
           row(0, ("app", "Application", "compute"), ("pri", "Primary", "database"), ("rep", "Readable replica", "database", "reports"))
           + row(1, ("sh1", "Shard A–M", "database"), ("sh2", "Shard N–Z", "database"), ("kv", "Key Vault", "security", "TDE / AE keys"))
           + row(2, ("mask", "Masking + RLS", "security"), ("aud", "Auditing + Defender", "security")),
           [S("problem", "Problem", "Busier every month, and full of sensitive data", "The database slows at month-end, reports compete with orders, and auditors ask who can see card numbers.", add=["app", "pri"], edges=[("app", "pri")]),
            S("technique", "Scale", "Four ways to scale", "Scale up: more vCores. Read scale-out: send reports to a readable replica. Elastic pool: share resources across databases. Sharding: split data across databases by a key.", add=["rep", "sh1", "sh2"], edges=[("pri", "rep", "ReadOnly"), ("app", "sh1"), ("app", "sh2")], learn=[0]),
            S("concept", "Encrypt", "At rest and in use", "TDE encrypts database files (on by default). Always Encrypted encrypts chosen columns in the app's driver, so even DBAs see only ciphertext.", add=["kv"], edges=[("kv", "pri")], learn=[1]),
            S("technique", "Control", "Hide, filter, record", "Dynamic data masking shows XXXX-1234 to support staff. Row-level security returns only a user's own rows. Auditing and Defender for SQL record and alert on suspicious activity.", add=["mask", "aud"], edges=[("mask", "pri"), ("pri", "aud")], learn=[2], warn="Masking is not encryption — privileged users still see the real values."),
            S("recap", "Recap", "Scale and protect", "Fast and safe.", recap=["Scale up / read scale-out / pool / shard", "TDE at rest; Always Encrypted from DBAs", "Masking, RLS, auditing, Defender for SQL"])]),
)
qa("AZ305-2.1.3", 2, "scenario", "Heavy reports slow down OLTP on a Business Critical database. You want to fix it without extra cost. What do you recommend?", [("Read scale-out with ApplicationIntent=ReadOnly for reports", "Correct: Business Critical includes a readable replica."), ("Scale up to double vCores", "Extra cost."), ("Move reports to a separate database copy every night", "Stale data and extra work."), ("Use Hyperscale named replicas", "Requires changing tier.")], "a", "Read scale-out uses the built-in readable replica at no extra cost.", SQL + "database/read-scale-out")
qa("AZ305-2.1.3", 3, "architecture", "A multi-tenant app will outgrow any single database. Each tenant's data must stay together and be movable. What do you recommend?", [("Shard by tenant across databases using elastic database tools", "Correct."), ("Scale up to the largest Business Critical size", "Still a single-database limit."), ("Read scale-out", "Helps reads only."), ("Add more indexes", "Not a scale-out strategy.")], "a", "Horizontal sharding with a shard map spreads tenants across databases.", SQL + "database/elastic-scale-introduction")
qa("AZ305-2.1.3", 2, "single", "Which tier lets you add up to 30 named replicas for independent read workloads?", [("Hyperscale", "Correct."), ("General Purpose", "No readable replicas."), ("Business Critical", "One built-in readable replica."), ("Basic", "No replicas.")], "a", "Hyperscale supports named replicas for read scale-out.", SQL + "database/service-tier-hyperscale-replicas")
qa("AZ305-2.1.4", 2, "scenario", "Database administrators must not be able to view social security numbers, but the app must use them. What do you recommend?", [("Always Encrypted on that column", "Correct."), ("Transparent data encryption", "Data is decrypted for anyone querying."), ("Dynamic data masking", "Privileged users see the real values."), ("Firewall rules", "Network control only.")], "a", "Always Encrypted keeps plaintext out of the database engine.", ML + "sql/relational-databases/security/encryption/always-encrypted-database-engine")
qa("AZ305-2.1.4", 2, "scenario", "Each regional sales manager must see only orders from their region in the same table. What do you recommend?", [("Row-level security", "Correct."), ("Dynamic data masking", "Masks values, not rows."), ("A separate database per region", "Unnecessary duplication."), ("TDE", "At-rest encryption only.")], "a", "RLS filters rows per user with security predicates.", ML + "sql/relational-databases/security/row-level-security")
qa("AZ305-2.1.4", 2, "multiple", "Which TWO features detect or record suspicious database activity?", [("Auditing", "Correct."), ("Microsoft Defender for SQL", "Correct: threat detection alerts."), ("Dynamic data masking", "Hides values."), ("Elastic pools", "Resource sharing.")], "ab", "Auditing records events; Defender for SQL detects threats such as SQL injection.", SQL + "database/security-overview")

